import { contactTopics, emailPattern, validateContact } from "../lib/contact";

// Runtime secrets extend bindings generated by `npm run cf:types`.
export interface ContactEnv extends Cloudflare.Env {
  RESEND_API_KEY?: string;
  CONTACT_TO_EMAIL?: string;
  CONTACT_FROM_EMAIL?: string;
}

function json(body: object, status = 200, headers: Record<string, string> = {}) {
  return Response.json(body, { status, headers: { "Cache-Control": "no-store", "X-Content-Type-Options": "nosniff", "X-Robots-Tag": "noindex", ...headers } });
}

function configured(env: ContactEnv) {
  return Boolean(env.RESEND_API_KEY && env.CONTACT_TO_EMAIL && emailPattern.test(env.CONTACT_TO_EMAIL) && env.CONTACT_FROM_EMAIL && emailPattern.test(env.CONTACT_FROM_EMAIL));
}

async function readBody(request: Request) {
  const reader = request.body?.getReader();
  if (!reader) return "";
  const chunks: Uint8Array[] = [];
  let size = 0;
  try {
    while (true) {
      const { done, value } = await reader.read();
      if (done) break;
      size += value.byteLength;
      if (size > 20000) { await reader.cancel(); return null; }
      chunks.push(value);
    }
    const bytes = new Uint8Array(size);
    let offset = 0;
    for (const chunk of chunks) { bytes.set(chunk, offset); offset += chunk.byteLength; }
    return new TextDecoder().decode(bytes);
  } finally { reader.releaseLock(); }
}

export default {
  async fetch(request: Request, env: ContactEnv): Promise<Response> {
    const url = new URL(request.url);
    if (url.pathname !== "/api/contact") {
      if (url.pathname.startsWith("/api/")) return json({ error: "Not found." }, 404);
      return env.ASSETS.fetch(request);
    }
    if (request.method === "GET") return json({ available: configured(env) });
    if (request.method !== "POST") return json({ error: "Method not allowed." }, 405, { Allow: "GET, POST" });
    if (request.headers.get("Origin") !== url.origin) return json({ error: "Please send your message from the foundation’s website." }, 403);
    if (!request.headers.get("Content-Type")?.toLowerCase().startsWith("application/json")) return json({ error: "Send a JSON message." }, 415);
    try {
      const body = await readBody(request);
      if (body === null) return json({ error: "Your message is too large. Please shorten it and try again." }, 413);
      let input: unknown;
      try { input = JSON.parse(body); } catch { return json({ error: "The message could not be read. Please try again." }, 400); }
      const { fields, errors } = validateContact(input);
      if (Object.keys(errors).length) return json({ error: "Please check the form and try again.", errors }, 422);
      if (!configured(env)) return json({ error: "Message delivery is being set up. Please check back soon." }, 503);
      const { success } = await env.CONTACT_RATE_LIMIT.limit({ key: `agape-contact:${request.headers.get("CF-Connecting-IP") || "local"}` });
      if (!success) return json({ error: "You’ve sent several messages. Please wait a minute before trying again." }, 429, { "Retry-After": "60" });
      const topic = contactTopics.find(({ value }) => value === fields.topic)!.label;
      const response = await fetch("https://api.resend.com/emails", {
        method: "POST",
        headers: { Authorization: `Bearer ${env.RESEND_API_KEY}`, "Content-Type": "application/json" },
        body: JSON.stringify({
          from: env.CONTACT_FROM_EMAIL, to: [env.CONTACT_TO_EMAIL], reply_to: fields.email,
          subject: `Agape website: ${topic}`,
          text: `Name: ${fields.name}\nEmail: ${fields.email}\nOrganization: ${fields.organization || "Not provided"}\nTopic: ${topic}\n\n${fields.message}`,
        }),
        signal: AbortSignal.timeout(10000),
      });
      if (!response.ok) {
        console.error(JSON.stringify({ event: "contact_delivery_failed", status: response.status }));
        return json({ error: "Your message couldn’t be sent. Please try again in a moment." }, 502);
      }
      return json({ ok: true });
    } catch {
      console.error(JSON.stringify({ event: "contact_request_failed" }));
      return json({ error: "We couldn’t confirm that your message was sent. Please try again in a moment." }, 502);
    }
  },
} satisfies ExportedHandler<ContactEnv>;
